                                '\n'
                                'int main()\n'
                                '{\n'
                                '    FILE *file;\n'
                                '\n'
                                '    file = fopen("student.txt", "w");\n'
                                '\n'
                                '    if(file == NULL)\n'
                                '    {\n'
                                '        printf("Unable to open file");\n'
                                '        return 1;\n'
